/** Overlay translated fields onto a Topic for the given locale.
 *  Falls back to English for any missing field or locale. */
export function localizeTopic(t: Topic, locale: Locale): Topic {
  if (locale === 'en') return t;
  const o = TOPICS_I18N[t.slug]?.[locale];
  if (!o) return t;
  return {
    ...t,
    title: o.title ?? t.title,
    summary: o.summary ?? t.summary,
    essay: o.essay ?? t.essay,
    microPrompt: o.microPrompt ?? t.microPrompt,
  };
}
